package com.zerostreams.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.net.*;
import android.speech.RecognizerIntent;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** ZeroPlay 2.3 test-only personalization/discovery hub. It never starts or alters playback. */
public class Zero23HubActivity extends Activity {
    private static final int VOICE=2301;
    private final ExecutorService io=Executors.newFixedThreadPool(3);
    private final Handler ui=new Handler(Looper.getMainLooper());
    private final Map<String,JSONObject> memory=new ConcurrentHashMap<>();
    private Zero23Store store; private LinearLayout content; private TextView status; private int ink,bg,surface,muted,accent; private boolean tv;

    @Override public void onCreate(Bundle state){super.onCreate(state);tv=BuildConfig.TV;store=new Zero23Store(this);palette();renderShell();loadDiscovery();}
    @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
    private void palette(){boolean light=store.core().getString("theme","dark").equals("light");bg=light?Color.rgb(243,245,249):Color.rgb(8,10,15);surface=light?Color.WHITE:Color.rgb(22,25,34);ink=light?Color.rgb(23,31,45):Color.rgb(244,247,250);muted=light?Color.rgb(80,94,112):Color.rgb(157,165,181);accent=light?Color.rgb(10,113,94):Color.rgb(101,230,204);}
    private int dp(float v){return(int)(getResources().getDisplayMetrics().density*v+.5f);}
    private TextView text(String value,float size,int color){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setPadding(dp(4),dp(4),dp(4),dp(4));return v;}
    private Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(ink);b.setTextSize(tv?15:13);b.setFocusable(true);b.setBackgroundColor(surface);b.setOnClickListener(v->action.run());b.setOnFocusChangeListener((v,f)->{if(f){store.setProfileValue("focusKey",label);v.setScaleX(1.03f);v.setScaleY(1.03f);}else{v.setScaleX(1f);v.setScaleY(1f);}});return b;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private void gap(ViewGroup p,int h){p.addView(new Space(this),new ViewGroup.LayoutParams(1,dp(h)));}
    private void heading(String title,String sub){TextView h=text(title,tv?25:21,ink);h.setTypeface(null,android.graphics.Typeface.BOLD);content.addView(h);if(sub!=null&&!sub.isEmpty())content.addView(text(sub,12,muted));gap(content,8);}
    private void section(String title,String sub){gap(content,18);TextView h=text(title,tv?20:18,ink);h.setTypeface(null,android.graphics.Typeface.BOLD);content.addView(h);if(sub!=null)content.addView(text(sub,12,muted));gap(content,6);}

    private void renderShell(){
        LinearLayout root=column();root.setBackgroundColor(bg);
        LinearLayout header=row();header.setPadding(dp(tv?28:16),dp(12),dp(16),dp(10));TextView brand=text("✦  ZERO PLAY 2.3 · TEST LAB",tv?22:18,ink);brand.setTypeface(null,android.graphics.Typeface.BOLD);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));header.addView(button("Back",this::finish));root.addView(header);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();content.setPadding(dp(tv?34:18),dp(18),dp(tv?34:18),dp(40));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        status=text("Building your 2.3 profile…",12,muted);status.setPadding(dp(18),dp(7),dp(18),dp(7));root.addView(status);setContentView(root);renderLocal();
    }
    private void renderLocal(){
        content.removeAllViews();JSONObject p=store.profile(),taste=store.taste();heading("Made for "+store.active()+" "+p.optString("avatar","🎬"),tasteCopy(taste));
        LinearLayout actions=row();actions.setWeightSum(3);actions.addView(button("🎲 Watchlist Roulette",this::roulette),new LinearLayout.LayoutParams(0,dp(tv?54:48),1));actions.addView(button("Quick panel",this::quickPanel),new LinearLayout.LayoutParams(0,dp(tv?54:48),1));actions.addView(button("What Changed",this::whatChanged),new LinearLayout.LayoutParams(0,dp(tv?54:48),1));content.addView(actions);
        section("Your Space","50-point personalization layer; playback remains frozen to 2.2.2 behavior.");
        stats();finishIt();seriesHub();collections();watchlistTools();calendar();profiles();appearance();systemTools();featureMap();tips();
    }
    private String tasteCopy(JSONObject taste){JSONArray g=taste.optJSONArray("genres"),d=taste.optJSONArray("decades"),l=taste.optJSONArray("languages");StringBuilder s=new StringBuilder("Taste Profile · ");JSONArray g0=g==null?null:g.optJSONArray(0),d0=d==null?null:d.optJSONArray(0),l0=l==null?null:l.optJSONArray(0);if(g0!=null)s.append(genreName(g0.optInt(0)));else s.append("still learning");if(d0!=null)s.append(" · ").append(d0.optInt(0)).append('s');if(l0!=null)s.append(" · ").append(l0.optString(0).toUpperCase(Locale.ROOT));return s.toString();}
    private String genreName(int id){switch(id){case 28:return"Action";case 12:return"Adventure";case 16:return"Animation";case 35:return"Comedy";case 80:return"Crime";case 99:return"Documentary";case 18:return"Drama";case 10751:return"Family";case 14:return"Fantasy";case 27:return"Horror";case 9648:return"Mystery";case 10749:return"Romance";case 878:return"Science Fiction";case 53:return"Thriller";default:return"Genre "+id;}}
    private void stats(){JSONArray history=store.history();Set<String> watch=store.watchlist();List<JSONObject> cont=store.continueItems(),finish=store.finishItems();LinearLayout grid=row();String[] labels={"Watchlist\n"+watch.size(),"History\n"+history.length(),"Continue\n"+cont.size(),"Finish It\n"+finish.size()};for(String label:labels){TextView v=text(label,tv?16:14,ink);v.setGravity(Gravity.CENTER);v.setBackgroundColor(surface);grid.addView(v,new LinearLayout.LayoutParams(0,dp(66),1));}content.addView(grid);}
    private void finishIt(){List<JSONObject> items=store.finishItems();section("Finish It","Titles at 65–94% progress. This view does not modify playback progress.");if(items.isEmpty())content.addView(text("Nothing near the finish line yet.",13,muted));else titleButtons(items,10,false);}
    private void seriesHub(){List<JSONObject> series=new ArrayList<>();for(JSONObject i:store.savedItems())if(i.optString("type").equals("series"))series.add(i);section("Series Hub + episode notifications","Follow active series; the Release Radar refresh checks next-airing metadata while this hub is open.");if(series.isEmpty())content.addView(text("Start or save a TV series to populate the hub.",13,muted));else titleButtons(series,12,true);}
    private void titleButtons(List<JSONObject> items,int limit,boolean follow){HorizontalScrollView sc=new HorizontalScrollView(this);sc.setHorizontalScrollBarEnabled(false);LinearLayout r=row();int n=0;for(JSONObject item:items){if(n++>=limit)break;String title=item.optString("title","Untitled");Button b=button((follow?"☆ ":"")+title,()->titleInfo(item));if(follow)b.setOnLongClickListener(v->{int id=tmdbId(item);if(id>0){store.follow("series",id,title);toast("Following "+title);}return true;});r.addView(b,new LinearLayout.LayoutParams(dp(tv?220:170),dp(tv?64:54)));}sc.addView(r);content.addView(sc);}
    private void collections(){section("Franchise progress + collection timelines","Existing ZeroPlay collections are summarized here and become timeline/franchise tracking groups in 2.3.");Set<String> names=store.core().getStringSet("collections",Collections.emptySet());if(names.isEmpty())content.addView(text("Create a collection in My Library to track a franchise or timeline.",13,muted));for(String name:new TreeSet<>(names)){Set<String> ids=store.core().getStringSet("collection:"+name,Collections.emptySet());content.addView(text(name+" · "+ids.size()+" saved titles",14,ink));}}
    private void watchlistTools(){section("Watchlist organization, Roulette & Voting","Votes are profile-local and never alter your saved watchlist.");Set<String> ids=store.watchlist();if(ids.isEmpty()){content.addView(text("Your watchlist is empty.",13,muted));return;}for(String id:ids){String saved=store.core().getString("saved:"+id,"");try{JSONObject item=new JSONObject(saved);LinearLayout r=row();TextView title=text(item.optString("title","Saved title"),14,ink);r.addView(title,new LinearLayout.LayoutParams(0,-2,1));r.addView(button("▲",()->{store.vote(id,1);renderLocal();}),new LinearLayout.LayoutParams(dp(48),dp(42)));TextView score=text(String.valueOf(store.vote(id)),14,ink);score.setGravity(Gravity.CENTER);r.addView(score,new LinearLayout.LayoutParams(dp(42),dp(42)));r.addView(button("▼",()->{store.vote(id,-1);renderLocal();}),new LinearLayout.LayoutParams(dp(48),dp(42)));content.addView(r);}catch(Exception ignored){}}}
    private void calendar(){section("Watch Calendar","Plan a movie night, episode, or release check-in.");content.addView(button("+ Add calendar item",this::calendarDialog));JSONArray rows=store.calendar();for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x!=null)content.addView(text(x.optString("date")+" · "+x.optString("title"),13,ink));}}
    private void profiles(){section("Household Profiles","Adult, Kids and Guest profiles with avatars and per-profile UI preferences.");LinearLayout r=row();Spinner list=new Spinner(this);List<String> names=store.profiles();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);list.setAdapter(adapter);list.setSelection(Math.max(0,names.indexOf(store.active())));r.addView(list,new LinearLayout.LayoutParams(0,dp(48),1));r.addView(button("Switch",()->{store.switchProfile(String.valueOf(list.getSelectedItem()));renderLocal();loadDiscovery();}),new LinearLayout.LayoutParams(-2,dp(48)));r.addView(button("+ Profile",this::profileDialog),new LinearLayout.LayoutParams(-2,dp(48)));content.addView(r);}
    private void appearance(){JSONObject p=store.profile();section("Per-profile UI, density & accessibility","Ambient focus, poster density, high contrast, large text, reduced motion and data-aware preferences.");LinearLayout presets=row();for(String x:new String[]{"beautiful","balanced","fast","data-saver","tv-performance"})presets.addView(button(x,()->{store.setPreset(x);renderLocal();}),new LinearLayout.LayoutParams(0,dp(tv?50:44),1));content.addView(presets);content.addView(toggle("High contrast",p.optBoolean("highContrast"),v->store.setProfileValue("highContrast",v)));content.addView(toggle("Large text",p.optBoolean("largeText"),v->store.setProfileValue("largeText",v)));content.addView(toggle("Reduced motion",p.optBoolean("reducedMotion"),v->store.setProfileValue("reducedMotion",v)));content.addView(toggle("Network/Data Saver artwork",p.optBoolean("dataSaver"),v->store.setProfileValue("dataSaver",v)));}
    interface BoolAction{void run(boolean value);}private Switch toggle(String label,boolean value,BoolAction action){Switch s=new Switch(this);s.setText(label);s.setTextColor(ink);s.setChecked(value);s.setOnCheckedChangeListener((v,c)->action.run(c));return s;}
    private void systemTools(){section("Storage, Smart Cache, Offline Catalog, Sync & Diagnostics","Local-first system tools. Backups and sync packets contain profile/enhancement settings, not playback secrets.");long coreBytes=0;for(Map.Entry<String,?> e:store.core().getAll().entrySet())coreBytes+=String.valueOf(e.getKey()).length()*2L+String.valueOf(e.getValue()).length()*2L;content.addView(text(String.format(Locale.ROOT,"2.3 state %.1f KB · Core app estimate %.1f KB · API cache %d entries",store.ownBytes()/1024f,coreBytes/1024f,memory.size()),13,muted));LinearLayout a=row();a.addView(button("Clear smart cache",()->{memory.clear();toast("2.3 smart cache cleared");}),new LinearLayout.LayoutParams(0,dp(48),1));a.addView(button("Export profile",this::exportProfile),new LinearLayout.LayoutParams(0,dp(48),1));a.addView(button("Import",this::importProfile),new LinearLayout.LayoutParams(0,dp(48),1));content.addView(a);LinearLayout b=row();b.addView(button("LAN sync packet",this::copySyncPacket),new LinearLayout.LayoutParams(0,dp(48),1));b.addView(button("Import packet",this::importSyncPacket),new LinearLayout.LayoutParams(0,dp(48),1));b.addView(button("Diagnostics",this::diagnostics),new LinearLayout.LayoutParams(0,dp(48),1));content.addView(b);}
    private void featureMap(){section("2.3 enhancement map · 50/50","Every point is wired into this branch for testing; network-backed rows degrade to local/offline information when unavailable.");for(int i=0;i<Zero23Store.FEATURES.length;i++)content.addView(text(String.format(Locale.ROOT,"%02d  %s  · ready to test",i+1,Zero23Store.FEATURES[i]),12,(i%2==0)?ink:muted));}
    private void tips(){section("Feature Tips","Tip: long-press a Series Hub title to follow it. MENU opens the TV quick panel; SEARCH launches voice search when available.");}

    private String key(){String configured=store.core().getString("tmdbKey","").trim();return configured.isEmpty()?BuildConfig.DEFAULT_TMDB_KEY:configured;}
    private JSONObject api(String path,String extra)throws Exception{String cacheKey=path+extra;JSONObject hit=memory.get(cacheKey);if(hit!=null)return hit;JSONObject data=ContentApi.tmdb(path,key(),extra);memory.put(cacheKey,data);return data;}
    private void loadDiscovery(){status.setText("Loading For You, Release Radar and discovery rows…");io.execute(()->{try{JSONObject taste=store.taste();int genre=0,decadeValue=2010;JSONArray g=taste.optJSONArray("genres"),d=taste.optJSONArray("decades");JSONArray g0=g==null?null:g.optJSONArray(0),d0=d==null?null:d.optJSONArray(0);if(g0!=null)genre=g0.optInt(0);if(d0!=null)decadeValue=d0.optInt(0);final int fg=genre,fd=decadeValue;List<Catalog.Item> forYou=ContentApi.tmdbRows(api(genre>0?"/discover/movie":"/movie/top_rated",genre>0?"&with_genres="+genre+"&sort_by=popularity.desc&vote_count.gte=100":"&page=1").getJSONArray("results"),"movie",false);List<Catalog.Item> upcoming=ContentApi.tmdbRows(api("/movie/upcoming","&region=PH&page=1").getJSONArray("results"),"movie",false);List<Catalog.Item> tvRows=ContentApi.tmdbRows(api("/tv/on_the_air","&page=1").getJSONArray("results"),"tv",false);List<Catalog.Item> ph=ContentApi.tmdbRows(api("/discover/movie","&region=PH&sort_by=popularity.desc&page=1").getJSONArray("results"),"movie",false);List<Catalog.Item> acclaim=ContentApi.tmdbRows(api("/discover/movie","&sort_by=vote_average.desc&vote_count.gte=1500&page=1").getJSONArray("results"),"movie",false);List<Catalog.Item> decade=ContentApi.tmdbRows(api("/discover/movie","&primary_release_date.gte="+decadeValue+"-01-01&primary_release_date.lte="+(decadeValue+9)+"-12-31&sort_by=popularity.desc&page=1").getJSONArray("results"),"movie",false);List<Catalog.Item> seasonal=ContentApi.tmdbRows(api("/discover/movie","&with_genres="+seasonalGenre()+"&sort_by=popularity.desc&page=1").getJSONArray("results"),"movie",false);ui.post(()->{if(isDestroyed())return;section("For You",fg>0?"Built from your strongest genre: "+genreName(fg):"High-rated starter picks while ZeroPlay learns your taste.");catalogButtons(forYou);section("Release Radar + Newly Added","Upcoming movies and currently airing TV.");catalogButtons(join(upcoming,tvRows));section("Popular in the Philippines","Region-aware discovery for PH.");catalogButtons(ph);section("Awards & Acclaim","High-rated titles with substantial audience vote counts.");catalogButtons(acclaim);section(fd+"s Rewind","Decade discovery from your taste profile.");catalogButtons(decade);section(seasonalTitle(),"Seasonal Home row adapts to the current month.");catalogButtons(seasonal);episodeNotifications();status.setText("ZeroPlay 2.3 test hub ready · playback unchanged");});}catch(Exception e){ui.post(()->status.setText("2.3 discovery offline · local profile tools remain available · "+e.getMessage()));}});}
    private List<Catalog.Item> join(List<Catalog.Item>a,List<Catalog.Item>b){ArrayList<Catalog.Item> out=new ArrayList<>(a);out.addAll(b);return out;}
    private void catalogButtons(List<Catalog.Item> rows){HorizontalScrollView sc=new HorizontalScrollView(this);sc.setHorizontalScrollBarEnabled(false);LinearLayout r=row();int n=0;for(Catalog.Item item:rows){if(n++>=20)break;Button b=button(item.title+"\n"+(item.raw.optInt("year")>0?item.raw.optInt("year")+" · ":"")+String.format(Locale.ROOT,"★ %.1f",item.raw.optDouble("rating")),()->titleInfo(item.raw));b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);r.addView(b,new LinearLayout.LayoutParams(dp(tv?250:190),dp(tv?78:66)));}sc.addView(r);content.addView(sc);}
    private int seasonalGenre(){int m=Calendar.getInstance().get(Calendar.MONTH)+1;return m==10?27:m==12?10751:m==2?10749:(m>=6&&m<=8)?12:35;}
    private String seasonalTitle(){int m=Calendar.getInstance().get(Calendar.MONTH)+1;return m==10?"Spooky Season":m==12?"Holiday Watch":m==2?"February Romance":m>=6&&m<=8?"Summer Adventures":"Seasonal Picks";}
    private void episodeNotifications(){JSONArray followed=store.follows("series");if(followed.length()==0)return;section("Episode notifications","Next-airing checks for followed series while the test hub is refreshed.");for(int i=0;i<followed.length();i++){JSONObject f=followed.optJSONObject(i);if(f==null)continue;content.addView(text("Following · "+f.optString("name"),13,ink));int id=f.optInt("id");io.execute(()->{try{JSONObject detail=api("/tv/"+id,"");JSONObject next=detail.optJSONObject("next_episode_to_air");if(next!=null)ui.post(()->content.addView(text(detail.optString("name")+" · S"+next.optInt("season_number")+" E"+next.optInt("episode_number")+" · "+next.optString("air_date"),13,accent)));}catch(Exception ignored){}});}}
    private int tmdbId(JSONObject item){String id=item.optString("id");try{if(id.matches("tmdb-(movie|series)-[0-9]+"))return Integer.parseInt(id.substring(id.lastIndexOf('-')+1));return item.optInt("tmdbId",0);}catch(Exception e){return 0;}}
    private void titleInfo(JSONObject item){String followLabel=item.optString("type").equals("series")?"Follow series":null;AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle(item.optString("title","Title")).setMessage(item.optString("description",item.optString("overview","No synopsis available."))).setPositiveButton("OK",null);if(followLabel!=null)b.setNeutralButton(followLabel,(d,w)->{int id=tmdbId(item);if(id>0){store.follow("series",id,item.optString("title"));toast("Following "+item.optString("title"));}});b.show();}
    private void roulette(){Set<String> ids=store.watchlist();if(ids.isEmpty()){toast("Your watchlist is empty.");return;}List<String> all=new ArrayList<>(ids);String id=all.get(new Random().nextInt(all.size()));try{JSONObject item=new JSONObject(store.core().getString("saved:"+id,"{}"));new AlertDialog.Builder(this).setTitle("Watchlist Roulette").setMessage("Tonight's pick:\n\n"+item.optString("title","Saved title")).setPositiveButton("Nice",null).show();}catch(Exception e){toast("Roulette picked a saved title: "+id);}}
    private void quickPanel(){JSONObject p=store.profile();new AlertDialog.Builder(this).setTitle("2.3 Quick Panel").setItems(new String[]{"Profile · "+store.active(),"Preset · "+p.optString("preset","balanced"),"Density · "+p.optString("density","balanced"),"Data Saver · "+(p.optBoolean("dataSaver")?"On":"Off"),"Open diagnostics"},(d,n)->{if(n==4)diagnostics();}).show();}
    private void whatChanged(){new AlertDialog.Builder(this).setTitle("What Changed in 2.3").setMessage("This test branch adds the 50-point personalization, discovery, profile, accessibility, cache, offline, sync, backup and diagnostics layer. Video player behavior and playback source implementations are intentionally unchanged from 2.2.2.").setPositiveButton("Got it",null).show();}
    private void calendarDialog(){LinearLayout box=column();EditText title=new EditText(this);title.setHint("Title / episode");EditText date=new EditText(this);date.setHint("YYYY-MM-DD");box.addView(title);box.addView(date);new AlertDialog.Builder(this).setTitle("Add to Watch Calendar").setView(box).setPositiveButton("Add",(d,w)->{String t=title.getText().toString().trim(),day=date.getText().toString().trim();if(!t.isEmpty()&&day.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")){store.calendarAdd(t,day);renderLocal();}}).setNegativeButton("Cancel",null).show();}
    private void profileDialog(){LinearLayout box=column();EditText name=new EditText(this);name.setHint("Profile name");Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"adult","kids","guest"}));box.addView(name);box.addView(mode);new AlertDialog.Builder(this).setTitle("New household profile").setView(box).setPositiveButton("Create",(d,w)->{store.addProfile(name.getText().toString(),String.valueOf(mode.getSelectedItem()));renderLocal();loadDiscovery();}).setNegativeButton("Cancel",null).show();}
    private void exportProfile(){String backup=store.backup();android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("ZeroPlay 2.3 profile",backup));Intent send=new Intent(Intent.ACTION_SEND).setType("application/json").putExtra(Intent.EXTRA_TEXT,backup);try{startActivity(Intent.createChooser(send,"Export ZeroPlay 2.3 profile"));}catch(Exception ignored){}toast("Profile JSON copied to clipboard.");}
    private void importProfile(){EditText input=new EditText(this);input.setHint("Paste ZeroPlay profile JSON");input.setMinLines(6);new AlertDialog.Builder(this).setTitle("Import profile").setView(input).setPositiveButton("Import",(d,w)->{if(store.restore(input.getText().toString())){toast("Profile imported");renderLocal();loadDiscovery();}else toast("Invalid ZeroPlay backup");}).setNegativeButton("Cancel",null).show();}
    private void copySyncPacket(){String packet=store.syncPacket();android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("ZeroPlay LAN sync packet",packet));toast("LAN sync packet copied. Paste it into ZeroPlay on the other device.");}
    private void importSyncPacket(){EditText input=new EditText(this);input.setHint("Paste sync packet");input.setMinLines(4);new AlertDialog.Builder(this).setTitle("Import LAN sync packet").setView(input).setPositiveButton("Import",(d,w)->{if(store.importPacket(input.getText().toString())){toast("Sync packet imported");renderLocal();loadDiscovery();}else toast("Invalid sync packet");}).setNegativeButton("Cancel",null).show();}
    private void diagnostics(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network active=Build.VERSION.SDK_INT>=23?cm.getActiveNetwork():null;StringBuilder s=new StringBuilder();s.append("ZeroPlay ").append(Zero23Store.VERSION).append('\n').append("Profile: ").append(store.active()).append('\n').append("Flavor: ").append(BuildConfig.TV?"Android TV":"Android Mobile").append(BuildConfig.LITE?" Lite":"").append('\n').append("Network: ").append(active!=null?"connected":"unknown/offline").append('\n').append(String.format(Locale.ROOT,"2.3 state: %.1f KB\n",store.ownBytes()/1024f)).append("TMDB key: ").append(key().isEmpty()?"missing":"configured").append('\n').append("Player files: frozen by 2.3 branch CI guard\n").append("Playback behavior: unchanged");new AlertDialog.Builder(this).setTitle("Diagnostics Health").setMessage(s.toString()).setPositiveButton("OK",null).show();}
    private void advancedSearch(String query){status.setText("Universal Search · "+query);io.execute(()->{try{JSONObject data=ContentApi.searchPageData(query,key(),1);List<Catalog.Item> rows=ContentApi.tmdbRows(data.getJSONArray("results"),"",true);JSONArray people=ContentApi.searchPeople(query,key());ui.post(()->{section("Universal Search · “"+query+"”","Movies, TV, people, aliases and typo-tolerant fallback.");catalogButtons(rows);if(people.length()>0){LinearLayout p=row();for(int i=0;i<Math.min(10,people.length());i++){JSONObject person=people.optJSONObject(i);if(person==null)continue;int id=person.optInt("id");String name=person.optString("name");p.addView(button("+ "+name,()->{store.follow("people",id,name);toast("Following "+name);}),new LinearLayout.LayoutParams(dp(tv?220:170),dp(52)));}content.addView(p);}status.setText("Search ready");});}catch(Exception e){ui.post(()->status.setText("Search unavailable · "+e.getMessage()));}});}
    private void voice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_PROMPT,"Search ZeroPlay");startActivityForResult(i,VOICE);}catch(Exception e){toast("Voice search is unavailable on this device.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VOICE&&result==RESULT_OK&&data!=null){ArrayList<String> rows=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(rows!=null&&!rows.isEmpty())advancedSearch(rows.get(0));}}
    @Override public boolean onKeyDown(int keyCode,android.view.KeyEvent event){if(keyCode==android.view.KeyEvent.KEYCODE_MENU){quickPanel();return true;}if(keyCode==android.view.KeyEvent.KEYCODE_SEARCH){voice();return true;}if(keyCode==android.view.KeyEvent.KEYCODE_R){roulette();return true;}return super.onKeyDown(keyCode,event);}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
